using UnityEngine;

namespace TowerDefense
{
    /// <summary>
    /// Small particle effects built in code: impact bursts, shockwave rings, auras and glowing circles.
    /// The materials are generated by the scene builder into Resources/Vfx so they ship in builds.
    /// </summary>
    public static class Vfx
    {
        private static Material additive, alphaBlended;

        /// <summary>Additive soft-dot material: glows and blooms with HDR colours.</summary>
        public static Material Additive => additive != null ? additive : additive = Resources.Load<Material>("Vfx/VfxAdditive");

        /// <summary>Alpha-blended soft-dot material: dust, smoke and mist.</summary>
        public static Material AlphaBlended => alphaBlended != null ? alphaBlended : alphaBlended = Resources.Load<Material>("Vfx/VfxAlpha");

        /// <summary>A one-shot spray of glowing particles. Negative gravity floats them upward.</summary>
        public static void Burst(Vector3 position, Color color, int count, float speed, float size, float lifetime, float gravity = 0f, bool additiveBlend = true)
        {
            ParticleSystem ps = Create("Burst", position, null, out GameObject go);
            ParticleSystem.MainModule main = ps.main;
            main.duration = lifetime;
            main.startLifetime = new ParticleSystem.MinMaxCurve(lifetime * 0.5f, lifetime);
            main.startSpeed = new ParticleSystem.MinMaxCurve(speed * 0.3f, speed);
            main.startSize = new ParticleSystem.MinMaxCurve(size * 0.5f, size);
            main.startColor = color;
            main.gravityModifier = gravity;
            main.maxParticles = count;

            ParticleSystem.ShapeModule shape = ps.shape;
            shape.shapeType = ParticleSystemShapeType.Sphere;
            shape.radius = 0.1f;

            Emit(ps, count);
            FadeAndShrink(ps);
            ps.GetComponent<ParticleSystemRenderer>().sharedMaterial = additiveBlend ? Additive : AlphaBlended;
            go.SetActive(true);
        }

        /// <summary>A flat ring of particles racing outward to the given radius: shows a splash's reach.</summary>
        public static void Ring(Vector3 position, Color color, float radius, float lifetime)
        {
            ParticleSystem ps = Create("Shockwave", position, null, out GameObject go);
            ParticleSystem.MainModule main = ps.main;
            main.duration = lifetime;
            main.startLifetime = lifetime;
            main.startSpeed = radius / lifetime;
            main.startSize = 0.45f;
            main.startColor = color;
            main.maxParticles = 48;

            ParticleSystem.ShapeModule shape = ps.shape;
            shape.shapeType = ParticleSystemShapeType.Circle;
            shape.radius = 0.05f;
            shape.radiusThickness = 0f;
            shape.rotation = new Vector3(90f, 0f, 0f);

            Emit(ps, 48);
            FadeAndShrink(ps);
            ps.GetComponent<ParticleSystemRenderer>().sharedMaterial = Additive;
            go.SetActive(true);
        }

        /// <summary>A short bright flash: one big particle that fades fast.</summary>
        public static void Flash(Vector3 position, Color color, float size)
        {
            ParticleSystem ps = Create("Flash", position, null, out GameObject go);
            ParticleSystem.MainModule main = ps.main;
            main.duration = 0.15f;
            main.startLifetime = 0.15f;
            main.startSpeed = 0f;
            main.startSize = size;
            main.startColor = color;
            main.maxParticles = 1;
            ParticleSystem.ShapeModule shape = ps.shape;
            shape.enabled = false;
            Emit(ps, 1);
            FadeAndShrink(ps);
            ps.GetComponent<ParticleSystemRenderer>().sharedMaterial = Additive;
            go.SetActive(true);
        }

        /// <summary>A looping swirl of motes around a transform, for a tier-3 tower.</summary>
        public static ParticleSystem Aura(Transform parent, Color color, float radius)
        {
            ParticleSystem ps = Create("Aura", parent.position, parent, out GameObject go);
            ParticleSystem.MainModule main = ps.main;
            main.loop = true;
            main.duration = 1f;
            main.startLifetime = 1.4f;
            main.startSpeed = 0.2f;
            main.startSize = new ParticleSystem.MinMaxCurve(0.08f, 0.2f);
            main.startColor = color * 2.2f;
            main.gravityModifier = -0.25f;
            main.simulationSpace = ParticleSystemSimulationSpace.World;
            main.stopAction = ParticleSystemStopAction.None;
            main.maxParticles = 60;

            ParticleSystem.EmissionModule emission = ps.emission;
            emission.rateOverTime = 22f;

            ParticleSystem.ShapeModule shape = ps.shape;
            shape.shapeType = ParticleSystemShapeType.Circle;
            shape.radius = radius;
            shape.radiusThickness = 0.2f;
            shape.rotation = new Vector3(90f, 0f, 0f);

            FadeAndShrink(ps);
            ps.GetComponent<ParticleSystemRenderer>().sharedMaterial = Additive;
            go.SetActive(true);
            return ps;
        }

        /// <summary>A glowing horizontal circle drawn with a LineRenderer in local space.</summary>
        public static LineRenderer Circle(Transform parent, float radius, int segments)
        {
            GameObject go = new GameObject("Ring");
            go.transform.SetParent(parent, false);
            LineRenderer line = go.AddComponent<LineRenderer>();
            line.sharedMaterial = Additive;
            line.useWorldSpace = false;
            line.loop = true;
            line.positionCount = segments;
            line.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
            line.receiveShadows = false;
            line.textureMode = LineTextureMode.Stretch;
            line.alignment = LineAlignment.TransformZ;
            go.transform.localRotation = Quaternion.Euler(90f, 0f, 0f);
            for (int i = 0; i < segments; i++)
            {
                float angle = i * Mathf.PI * 2f / segments;
                line.SetPosition(i, new Vector3(Mathf.Cos(angle), Mathf.Sin(angle), 0f) * radius);
            }
            return line;
        }

        private static ParticleSystem Create(string name, Vector3 position, Transform parent, out GameObject go)
        {
            // Configured while inactive so the system doesn't start playing with default settings.
            go = new GameObject(name);
            go.SetActive(false);
            if (parent != null) go.transform.SetParent(parent, false);
            go.transform.position = position;
            ParticleSystem ps = go.AddComponent<ParticleSystem>();
            ParticleSystem.MainModule main = ps.main;
            main.loop = false;
            main.playOnAwake = true;
            main.simulationSpace = ParticleSystemSimulationSpace.World;
            main.stopAction = ParticleSystemStopAction.Destroy;
            main.scalingMode = ParticleSystemScalingMode.Hierarchy;

            ParticleSystemRenderer renderer = ps.GetComponent<ParticleSystemRenderer>();
            renderer.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
            renderer.receiveShadows = false;
            return ps;
        }

        private static void Emit(ParticleSystem ps, int count)
        {
            ParticleSystem.EmissionModule emission = ps.emission;
            emission.rateOverTime = 0f;
            emission.SetBursts(new[] { new ParticleSystem.Burst(0f, (short)count) });
        }

        private static void FadeAndShrink(ParticleSystem ps)
        {
            ParticleSystem.ColorOverLifetimeModule colour = ps.colorOverLifetime;
            colour.enabled = true;
            Gradient fade = new Gradient();
            fade.SetKeys(
                new[] { new GradientColorKey(Color.white, 0f), new GradientColorKey(Color.white, 1f) },
                new[] { new GradientAlphaKey(1f, 0f), new GradientAlphaKey(0.8f, 0.4f), new GradientAlphaKey(0f, 1f) });
            colour.color = fade;

            ParticleSystem.SizeOverLifetimeModule size = ps.sizeOverLifetime;
            size.enabled = true;
            size.size = new ParticleSystem.MinMaxCurve(1f, AnimationCurve.Linear(0f, 1f, 1f, 0.3f));
        }
    }
}
